# Smilei namelist generated by scripts/lwfa/lwfa.jl from case "lwfa-2d" (plasma).
# Do not edit; regenerate from the case file. Units: Smilei normalized, reference frequency = ω₀ (A1).
import math
import numpy as np

Main(
    geometry = "2Dcartesian",
    interpolation_order = 2,
    cell_length = [0.1308996938995747, 0.5235987755982988],
    number_of_cells = [2304, 384],
    timestep = 0.12064178849259245,
    simulation_time = 1300.2168754789152,
    number_of_patches = [64, 8],
    EM_boundary_conditions = [["silver-muller"], ["periodic"]],
    solve_poisson = False,
    random_seed = 1,
    print_every = 500,
)

MovingWindow(
    time_start = 256.0,
    velocity_x = 1.0,
)

# The laser is applied 2 cells behind xmin, as sin(t) of the run's time: focus, center and
# phase_offset put the case's pulse (a cosine from the envelope's peak, with the Gouy phase) on x = 0
# (smilei_laser in scripts/lwfa/lwfa.jl).
LaserGaussian2D(
    box_side = "xmin",
    a0 = 2.0,
    omega = 1.0,
    focus = [320.26179938779916, 100.53096491487338],
    waist = 28.0,
    polarization_phi = 0.0,
    time_envelope = tgaussian(start = 0.0, duration = 216.08487528436618, fwhm = 43.29283978020028, center = 108.04243764218309),
    phase_offset = 4.304237029982232,
)

DiagScalar(every = 50, precision = 10)

def plasma_density(x, y):
    s = np.clip((x - 260.0) / 60.0, 0.0, 1.0)
    return 0.01 * np.sin(0.5 * math.pi * s)**2

for name, charge, mass, frozen in (("electron", -1.0, 1.0, 0.0), ("ion", 1.0, 1836.15267343, 5200.626218338675)):
    Species(
        name = name,
        position_initialization = "regular",
        regular_number = [2, 2],
        momentum_initialization = "cold",
        particles_per_cell = 4,
        mass = mass,
        charge = charge,
        number_density = plasma_density,
        time_frozen = frozen,
        boundary_conditions = [["remove", "remove"], ["periodic", "periodic"]],
    )

# 0: the window's spectrum; 1 and 2: the same cell by cell over the 72 cells at its back and at its
# front, which the reader takes off outside the region all three codes hold (spectrum_region)
DiagParticleBinning(
    deposited_quantity = "weight",
    every = 829,
    species = ["electron"],
    axes = [["ekin", 0.0, 100.0, 500]],
)
DiagParticleBinning(
    deposited_quantity = "weight",
    every = 829,
    species = ["electron"],
    axes = [["moving_x", 0.0, 9.42477796076938, 72], ["ekin", 0.0, 100.0, 500]],
)
DiagParticleBinning(
    deposited_quantity = "weight",
    every = 829,
    species = ["electron"],
    axes = [["moving_x", 292.16811678385073, 301.59289474462014, 72], ["ekin", 0.0, 100.0, 500]],
)

DiagFields(
    every = 829,
    fields = ["Ex", "Ey", "Rho_electron"],
    datatype = "double",
)
